/**
 * A typed handle to an org user. Reference-only: the EDK never creates,
 * invites, or updates users — this ref exists so builders that point at
 * a user do so type-safely instead of accepting a raw id string.
 *
 * `email` is required because the user catalog namespaces handles by it
 * (`users.aliceAtAcmeDotCom`); `id` is what the serializer sends.
 */
export interface UserRef {
    readonly id: string;
    readonly email: string;
    readonly firstName?: string;
    readonly lastName?: string;
}
export declare function user(opts: {
    id: string;
    email: string;
    firstName?: string;
    lastName?: string;
}): UserRef;
